['119-inv-03b','F06-C03','가장 심하게 탄 지점이 발견되었다. 가장 적절한 조사 태도는?',['환기·진압·붕괴 등 흔적 변형요인을 함께 검토한 뒤 발화부 가설을 검증한다','가장 심하게 탔으므로 즉시 발화부로 확정한다','전기제품이 있으면 무조건 전기화재로 확정한다','관계자 진술과 관계없이 사진을 폐기한다'],0,'high','사례형',['정답. 소손정도 하나가 아니라 흔적을 변화시킨 요소와 다른 자료를 종합한다.','심한 소손은 발화부 판단의 단서일 수 있지만 단독 확정근거가 아니다.','점화가능성과 실제 발화과정을 검증해야 한다.','사진은 객관적 현장기록으로 보존해야 한다.']],
['119-inv-04a','F06-C04','화재피해 조사자료로 가장 적절한 것은?',['피해대상별 사진·도면·목록과 조사범위·시점을 함께 기록한다','조사자의 느낌만 문장으로 남긴다','재산피해만 기록하고 인명피해는 제외한다','원인조사와 모순되어도 검토하지 않는다'],0,'mid','기록형',['정답. 제3자가 재검토할 수 있는 객관적 증빙과 범위·시점이 필요하다.','주관적 인상만으로 피해를 증명하기 어렵다.','인명과 재산피해를 모두 조사대상으로 본다.','원인·피해 자료의 모순은 재검토 신호가 된다.']],
['119-inv-04b','F06-C04','화재피해 조사와 원인조사의 관계로 가장 적절한 것은?',['각각 목적은 다르지만 서로 모순되는지 교차검토할 필요가 있다','두 조사는 절대 서로 관련이 없다','피해조사가 끝나면 원인자료는 폐기한다','피해액이 크면 자동으로 발화원인이 결정된다'],0,'high','연계형',['정답. 별도 영역이지만 연소확대와 피해범위가 합리적으로 일치하는지 검토한다.','같은 화재의 사실관계를 다루므로 완전히 분리된 것은 아니다.','원인자료는 조사근거로 보존해야 한다.','피해규모만으로 발화원인을 결정할 수 없다.']]
