  '구급기록지는 법적 소송이나 범죄현장 관련 사건에서 중요한 증거가 될 수 있으므로 정확하고 간결하게 작성해야 한다. 잘못된 기록을 숨기기 위한 위조·변조는 환자에게 위해를 주고 구급대원에게 법적 책임을 초래할 수 있다.',
