  '통증 문진은 OPQRST를 사용한다. Onset, Provocation/Palliation, Quality, Region/Radiation, Severity, Time 순으로 시작·악화/완화 요인·성격·부위/방사통·강도·시간 경과를 확인한다.',
  'SAMPLE에서는 증상/징후, 알레르기, 약물, 과거력, 마지막 섭취, 발생 상황을 확인한다. 가임기 여성은 생리주기·무월경·질출혈 등 산부인과적 응급 가능성과 관련된 민감한 병력도 환자 본인에게 직접 확인한다.',
