 summary:'한랭손상은 전신 저체온증과 국소 손상으로 나뉘며, 더 이상의 열손실을 막고 환자를 조심스럽게 다루며 호흡·순환을 지지하고 재동결 위험이 있는 현장 해동을 피하는 것이 중요하다.',
 detail:[
  '저체온증은 중심체온 35℃ 이하로 정의하며 체온이 낮아질수록 의식·근육기능·호흡·맥박이 저하된다. 중증에서는 맥박이 매우 느려지고 촉지가 어려울 수 있어 평가에 충분한 시간을 둔다.',
  '위험요인은 추위 노출뿐 아니라 소아·노인, 저혈당·패혈증, 약물·알코올, 화상·머리/척추손상·쇼크, 익수 등이 있다. 물에서는 공기보다 열전도가 훨씬 빨라 저체온이 빠르게 진행될 수 있다.',
  '처치 목표는 추운 환경에서 이동, 추가 열손실 차단, 기도 유지, 호흡·순환 지지다. 젖거나 조이는 옷을 제거하고 보온하며 의식이 명료한 환자는 가슴·목·겨드랑이·서혜부 등 중심부에 온열을 적용할 수 있다.',
  '저체온에서는 호흡과 맥박이 매우 느릴 수 있어 교재는 CPR 여부 판단 전 적어도 30~45초간 평가하도록 제시한다. 환자는 조심스럽게 이동하고 걷게 하거나 팔다리를 마사지하지 않는다.',
  '국소 한랭손상은 표재성 동창과 깊은 동상으로 구분할 수 있다. 재가온 후 다시 얼 위험이 있다면 현장에서 녹이지 않으며, 손상부위를 문지르거나 마사지·물집 파열·직접 열 적용을 피한다.'
 ],
 must:['저체온증 = 중심체온 35℃ 이하','중증 저체온에서 호흡·맥박 확인을 충분히 시행(교재 30~45초)','젖은 옷 제거·보온·중심부 가온','팔다리 마사지 금지','재동결 위험 시 현장 해동 금지'],
 traps:['저체온 환자의 느린 맥박을 짧게 확인하고 곧바로 무맥으로 단정하지 않는다.','동상 부위를 비비거나 직접 뜨거운 열원에 대지 않는다.'],
 compare:[['전신 저체온증','중심체온 저하·의식/호흡/순환 영향'],['국소 한랭손상','귀·코·손발 등 말단 조직 손상']],
