  '의심 징후로 회복단계가 서로 다른 여러 손상, 설명된 손상기전과 맞지 않는 손상, 담배자국 등 선명한 화상, 반복적인 구급신고, 보호자의 부적절하거나 회피적인 답변 등이 제시된다.',
  '방임과 관련해서는 아동을 위험환경에 혼자 두는 것, 위험물 안전조치 부족, 만성질환 치료 미이행, 영양실조 등을 살핀다.',
  '보호자가 평가·이송을 방해하거나 거부해 아동의 안전이 위협되면 경찰 등 관계기관의 도움을 요청할 수 있다. 학대·방임 의심 소견은 감정적 판단이 아니라 관찰된 사실을 객관적으로 기록하고 이송기관에 알린다.',
  '소아 처치의 우선순위는 성인과 마찬가지로 기도·호흡·순환이지만, 아동은 단순한 성인의 축소판이 아니므로 발달·해부·생리 차이를 고려한다.'
