 traps:['의심만으로 보호자를 비난하거나 단정하지 않는다.','주관적 표현 대신 관찰 사실·발언·손상위치를 객관적으로 기록한다.'],
 compare:[['학대','적극적·부적절한 행동으로 손상 초래'],['방임','필요한 보호·치료·영양·안전관리 부족']],
 flow:['아동 ABC/안전 우선','손상·환경 관찰','설명과 손상기전 비교','객관적 기록','필요 시 경찰 협조','이송기관 보고']
