'use strict';
(()=>{
const V=window.AITUTOR_V9=window.AITUTOR_V9||{};
const P=V.contentPacks?.authored;if(!P)return;
const put=(id,x)=>{P[id]={status:'scope-verified',compare:[],flow:[],must:[],traps:[],...x,detail:(x.detail||[]),deepSections:x.deepSections||[],sourcePrecision:x.sourcePrecision||'official-scope-pending-page-anchor'}};
const sec=(title,body,bullets=[])=>({title,body,bullets});

put('F05-C01',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'「위험물안전관리법」에서 위험물은 인화성 또는 발화성 등의 성질을 가지는 것으로서 대통령령이 정하는 물품을 말하며, 시행령 별표 1에서 제1류부터 제6류까지 품명과 지정수량을 정한다.',detail:['위험물은 제1류 산화성고체, 제2류 가연성고체, 제3류 자연발화성물질 및 금수성물질, 제4류 인화성액체, 제5류 자기반응성물질, 제6류 산화성액체로 구분한다.','지정수량은 위험물의 종류별 위험성을 고려해 대통령령으로 정한 수량이며 제조소·저장소·취급소의 설치허가 등에서 최저 기준이 되는 수량이다.','특수가연물은 위험물안전관리법의 제1류~제6류 분류가 아니라 「화재의 예방 및 안전관리에 관한 법률」 체계에서 별도로 정하는 가연물 기준이므로 구분해야 한다.'],must:['1류 산화성고체','2류 가연성고체','3류 자연발화성·금수성','4류 인화성액체','5류 자기반응성','6류 산화성액체','지정수량은 품명별 위험성에 따라 정한 법적 기준수량'],traps:['특수가연물을 위험물 제7류처럼 취급하지 않는다.','류만 보고 물 사용 가능·금지를 일률적으로 판단하지 않는다.','지정수량과 특수가연물의 기준수량을 같은 개념으로 혼동하지 않는다.'],source:'위험물안전관리법 제2조 · 위험물안전관리법 시행령 별표 1 · 2026 예방실무2 PDF 345·385쪽',officialLinks:[{label:'국가법령정보센터 위험물안전관리법 제2조',url:'https://www.law.go.kr/LSW/lsLinkCommonInfo.do?lsJoLnkSeq=1033761137'}],deepSections:[sec('법적 정의','위험물안전관리법은 인화성 또는 발화성 등의 성질을 가지며 대통령령이 정하는 물품을 위험물로 정의한다.'),sec('류별 분류와 지정수량','시행령 별표 1에서 위험물을 제1류부터 제6류까지 구분하고 각 품명별 지정수량을 정한다. 지정수량은 저장·취급 규제와 제조소등 설치허가 판단의 기본 수량기준이다.'),sec('특수가연물과의 구분','특수가연물은 화재예방법 체계의 별도 개념이다. 위험물의 류별 지정수량과 특수가연물의 품명별 기준수량은 적용 법령과 기준이 다르다.'),sec('지정수량과 저장 규제의 연결','위험물안전관리법 시행령 제3조는 별표 1의 위험물별 수량을 지정수량으로 정하고, 같은 시행령 제4조는 지정수량 이상의 위험물을 저장하기 위한 장소와 저장소의 구분을 별표 2로 정한다. 따라서 시험에서는 품명·지정수량·저장소 구분을 서로 연결하되 특수가연물 기준과 섞지 않아야 한다.')]});
put('F05-C02',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제1류 위험물은 산화성고체로서 자체가 잘 타기보다 다른 물질의 연소를 강하게 도울 수 있다는 점이 핵심이다.',detail:['가연물·환원성 물질과 접촉하면 연소가 급격히 진행될 수 있어 혼촉 위험을 중요하게 본다.','가열·충격·오염 등으로 분해가 촉진될 수 있으므로 물질별 성상을 확인해 대응해야 한다.'],must:['산화성고체','가연물과의 혼촉 위험','물질별 예외 확인'],traps:['제1류를 일반 가연성 고체로 분류하지 않는다.'],source:'2026 예방실무2 PDF 385쪽',deepSections:[sec('핵심원리','연료 역할보다 산소공급·산화 촉진 역할을 이해하면 다른 류와 구분하기 쉽다.'),sec('현장판단','주변 가연물과 분리하고 열·오염·혼촉 가능성을 먼저 확인한다.')]});
put('F05-C03',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제2류 위험물은 가연성고체로서 불꽃·열에 의해 연소하기 쉽고 일부 금속분 등은 소화방법 선택에 주의해야 한다.',detail:['고체 가연물이라도 입자가 미세할수록 표면적이 커져 연소가 빨라질 수 있다.','금속분 등은 물과의 반응 가능성을 확인해야 하므로 일반 고체화재와 같은 방식으로 단정하지 않는다.'],must:['가연성고체','미세분말의 빠른 연소 가능성','금속분의 물 반응성 주의'],traps:['모든 제2류에 물을 일률적으로 적용한다고 외우지 않는다.'],source:'2026 예방실무2 PDF 407쪽',deepSections:[sec('왜 위험한가','표면적·점화원·분진 상태가 연소속도에 영향을 준다.'),sec('문제풀이','가연성고체라는 공통점과 품목별 금수성 여부를 분리해서 본다.')]});
put('F05-C04',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제3류는 자연발화성 또는 금수성 물질로, 공기 또는 물과의 접촉 자체가 위험요인이 될 수 있다.',detail:['자연발화성 물질은 공기 중에서 스스로 발열·발화할 수 있고, 금수성 물질은 물과 접촉해 가연성가스나 열을 발생시킬 수 있다.','따라서 물을 사용하는 일반적인 냉각소화가 오히려 위험을 키울 수 있어 물질 식별이 우선이다.'],must:['자연발화성','금수성','물질 확인 전 물 사용 주의'],traps:['제3류 화재에 무조건 물을 방사하는 선택지를 경계한다.'],source:'2026 예방실무2 PDF 428쪽',deepSections:[sec('핵심구분','공기와의 반응 위험인지, 물과의 반응 위험인지 구분한다.'),sec('현장판단','누출물의 정체를 확인하기 전 물과 접촉시키지 않는 보수적 접근이 중요하다.')]});
put('F05-C05',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제4류는 인화성액체로, 액면에서 발생한 증기가 공기와 혼합되어 점화되는 구조를 이해해야 한다.',detail:['액체 자체보다 증기의 발생과 확산, 점화원 접촉이 화재위험의 핵심이다.','유면화재에서는 포 등으로 증기 발생과 산소접촉을 억제하는 개념이 중요하며, 직접적인 물줄기가 액체를 퍼뜨릴 수 있는 상황도 고려한다.'],must:['인화성액체','증기-공기 혼합','유면 피복·증기억제'],traps:['액체 자체가 기체 없이 바로 타는 것으로 설명한 선지에 주의한다.'],source:'2026 예방실무2 PDF 449쪽',deepSections:[sec('연소 메커니즘','인화성액체는 표면에서 증발한 증기가 연소한다는 점이 핵심이다.'),sec('소화 연결','냉각뿐 아니라 증기 발생 억제와 액면 피복을 함께 생각한다.')]});
put('F05-C06',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제5류는 자기반응성물질로서 자체 분해반응이 빠르게 진행되며 열·충격 등에 의해 폭발적 반응으로 이어질 수 있다.',detail:['외부에서 산소를 계속 공급하지 않아도 분해반응이 지속될 수 있는 물질이 있어 일반적인 질식만으로 충분하지 않을 수 있다.','가열·충격·마찰 등에 민감할 수 있으므로 물질의 안정성과 분해특성을 함께 본다.'],must:['자기반응성','열·충격·마찰 주의','급격한 분해 가능성'],traps:['산소를 차단하면 모든 제5류 반응이 즉시 멈춘다고 단정하지 않는다.'],source:'2026 예방실무2 PDF 496쪽',deepSections:[sec('핵심원리','자체 분해에 필요한 반응성이 물질 내부에 존재할 수 있다는 점이 다른 가연물과 다르다.'),sec('현장판단','가열된 용기·밀폐공간·충격 가능성을 함께 평가한다.')]});
put('F05-C07',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'제6류는 산화성액체로서 강한 산화작용으로 다른 가연물의 연소를 촉진할 수 있다.',detail:['자체가 연료라기보다 산화제로 작용하는 성격이 중요하다.','가연성·환원성 물질과 혼촉될 경우 강한 반응이 일어날 수 있으므로 누출물의 격리와 혼촉 방지가 중요하다.'],must:['산화성액체','혼촉 위험','가연물·환원성물질과 분리'],traps:['제6류를 인화성액체인 제4류와 혼동하지 않는다.'],source:'2026 예방실무2 PDF 523쪽',deepSections:[sec('제4류와 비교','제4류는 연료가 되는 인화성액체, 제6류는 산화를 촉진하는 산화성액체라는 구분이 핵심이다.')]});
put('F05-C08',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'위험물화재는 류별 성상뿐 아니라 보일오버 같은 특수현상과 저장·용기 상태를 함께 판단해야 한다.',detail:['유류 탱크화재에서는 열이 액면 아래로 전달되어 수분층이 급격히 기화하면서 연소 중인 유류가 넘쳐 분출되는 보일오버 위험을 고려한다.','위험물 대응은 물질 식별 → 용기·누출 상태 → 점화원 → 물과의 반응성 → 적합한 소화수단 순으로 판단하는 것이 안전하다.'],must:['보일오버 개념','물질 식별 우선','류별·품목별 소화방법 확인'],traps:['위험물이라는 이유만으로 모든 화재에 같은 소화약제를 적용하지 않는다.'],source:'2026 소방전술1 PDF 319쪽 · 예방실무2 PDF 536쪽',deepSections:[sec('보일오버','탱크 내부 수분의 급격한 기화와 뜨거운 유류의 분출 위험을 연결한다.'),sec('현장 의사결정','물질명·UN 정보·용기상태·누출범위·배수 방향까지 함께 본다.')]});

put('F06-C01',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'화재조사는 화재의 원인과 피해상황을 과학적·객관적으로 규명해 재발방지와 제도개선에 활용하는 활동이다.',detail:['현장에 남은 흔적은 진압·구조·철거 과정에서 쉽게 변형되므로 조사 가능한 상태를 보존하는 것이 중요하다.','원인조사와 피해조사는 서로 연결되지만 목적과 기록 항목을 구분해 이해한다.'],must:['객관적 사실기록','원인 규명','피해 조사','재발방지 활용'],traps:['추정만으로 원인을 확정하거나 현장 흔적을 임의로 훼손하지 않는다.'],source:'2026 소방전술1(화재2) PDF 269·270쪽',deepSections:[sec('왜 필요한가','원인 규명은 책임판단뿐 아니라 예방정책·소방시설 개선·교육에 활용된다.')]});
put('F06-C02',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'화재조사는 현장안전 확보와 보존, 관찰·기록, 관계자 정보수집, 흔적 분석을 체계적으로 진행한다.',detail:['현장 사진·영상·도면·관계자 진술 등 서로 다른 자료를 종합해 판단하고 하나의 단서만으로 결론을 내리지 않는다.','발화 가능 구역을 좁혀갈 때 화재패턴과 연소흔적이 진압활동·환기·붕괴로 변형됐을 가능성도 고려한다.'],must:['현장보존','사진·도면·진술','다중근거 종합'],traps:['화재패턴 하나만으로 발화원을 단정하지 않는다.'],source:'2026 소방전술1(화재2) PDF 276·282쪽',deepSections:[sec('절차적 사고','안전확보 → 보존 → 기록 → 정보수집 → 분석 → 결론의 흐름으로 이해한다.')]});
put('F06-C03',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'발화부는 화재가 시작된 위치, 발화원인은 그 위치에서 점화가 일어난 원인과 과정을 뜻하므로 구분해야 한다.',detail:['전기·불꽃·고온표면·화학반응 등 가능한 점화원을 검토하고 주변 가연물과의 접촉 가능성을 함께 본다.','원인을 판정할 때는 관찰사실과 가설을 구분해 기록해야 한다.'],must:['발화부 ≠ 발화원인','점화원 + 가연물 + 경과를 종합'],traps:['가장 심하게 탄 곳이 항상 발화부라고 단정하지 않는다.'],source:'2026 소방전술1(화재2) PDF 282·297쪽',deepSections:[sec('Fact / Inference','관찰한 사실과 그 사실에서 추론한 원인을 구분하면 조사 신뢰도가 높아진다.')]});
put('F06-C04',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'화재피해 조사는 인명·재산·소실 범위 등을 일관된 기준으로 확인하고 증빙 가능한 형태로 기록하는 과정이다.',detail:['건물·내용물·설비 등 피해대상을 구분하고 사진·목록·도면 등으로 객관적 근거를 남긴다.','피해조사 수치와 원인조사 결론이 서로 모순되지 않는지 검토하는 과정도 중요하다.'],must:['인명피해','재산피해','객관적 증빙'],traps:['피해금액이나 소실범위를 현장 인상만으로 결정하지 않는다.'],source:'2026 소방전술1(화재2) PDF 287·294쪽',deepSections:[sec('기록 품질','나중에 제3자가 재검토할 수 있도록 근거가 남는 기록을 만든다.')]});

put('F07-C01',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'소방시설은 기능에 따라 소화설비·경보설비·피난구조설비·소화용수설비·소화활동설비로 구분한다.',detail:['시험에서는 구체적인 설치기준보다 각 설비가 무엇을 감지·알리고, 어떻게 소화하거나 피난·소방활동을 지원하는지 묻는 방식이 핵심이다.'],must:['소화','경보','피난구조','소화용수','소화활동'],traps:['설비 명칭을 다른 기능군으로 바꿔 놓은 선지에 주의한다.'],source:'2026 예방실무1 PDF 17쪽',deepSections:[sec('범위 원칙','소방학개론에서는 종류·작동원리·사용법을 중심으로 보고 세부 설치기준은 별도 법규 영역으로 구분한다.')]});
put('F07-C02',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'소화기구는 화재 초기 단계에서 사람이 직접 사용해 연소를 억제하는 가장 기본적인 소화설비다.',detail:['화재 종류와 소화약제의 적응성을 맞추는 것이 핵심이며, 사용자는 안전한 퇴로를 확보한 상태에서 화점의 근원을 향해 방사한다.'],must:['초기소화','화재종류-약제 적응성','퇴로 확보'],traps:['대피로가 차단되는 상황에서 소화기 사용을 계속하지 않는다.'],source:'2026 예방실무1 PDF 207쪽',deepSections:[sec('사용 판단','초기 화재라도 연기·열이 급격히 커지면 소화보다 대피와 신고를 우선한다.')]});
put('F07-C03',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'옥내소화전은 건물 내부의 수원·펌프·배관·호스·관창을 이용해 사람이 화재에 방수하는 설비다.',detail:['기동 방식은 설비형식에 따라 다르지만 기본적으로 방수구에서 호스를 전개하고 밸브를 개방해 물을 공급하는 구조다.','호스가 꼬이거나 급격한 반동이 생기지 않도록 방수 전 전개상태와 인원을 확인한다.'],must:['수원·펌프·배관·방수구·호스·관창','수동 방수'],traps:['스프링클러처럼 헤드가 자동으로 열려 방수하는 설비로 혼동하지 않는다.'],source:'2026 예방실무1 PDF 247쪽',deepSections:[sec('작동 흐름','수원/펌프 → 배관 → 방수구 → 호스/관창 → 화점 방수')]});
put('F07-C04',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'옥외소화전은 건축물 외부에서 소방대 또는 관계자가 호스를 연결해 방수할 수 있도록 하는 소화설비다.',detail:['대규모 건축물이나 외부 화재 대응에서 외부 수원을 신속히 사용할 수 있게 하는 목적을 이해한다.'],must:['외부 방수거점','호스 연결','소방활동 지원'],traps:['옥내소화전과 설치 위치·사용상황을 뒤바꾸지 않는다.'],source:'2026 예방실무1 PDF 273쪽',deepSections:[sec('옥내와 비교','옥내는 건물 내부 방수, 옥외는 외부에서 화재진압에 필요한 방수거점을 제공한다.')]});
put('F07-C05',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'스프링클러는 화재열에 의해 해당 구역의 폐쇄형 헤드가 개방되면 배관의 물이 자동 방수되는 대표적인 자동소화설비다.',detail:['일반적인 폐쇄형 시스템에서는 화재열로 감열부가 작동한 헤드만 열리고, 배관 압력변화와 알람밸브·펌프 작동을 통해 지속적으로 물이 공급된다.','모든 헤드가 동시에 열리는 것으로 이해하면 안 되며 개방형 헤드를 사용하는 방식은 별도 구조로 구분한다.'],must:['열 감지 → 헤드 개방 → 방수','압력변화 → 경보/펌프 연계','폐쇄형은 작동한 헤드 중심 방수'],traps:['화재경보가 울리면 모든 폐쇄형 헤드가 동시에 열리는 것으로 설명한 선지는 틀리다.'],source:'2026 예방실무1 PDF 284쪽',deepSections:[sec('작동원리','헤드의 감열부가 화재열을 직접 받아 작동한다는 점이 자동화재탐지설비의 감지기와 다르다.'),sec('시험포인트','습식·건식·준비작동식·일제살수식은 배관/헤드/밸브 작동방식 차이를 중심으로 비교한다.')]});
put('F07-C06',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'간이스프링클러와 화재조기진압용 스프링클러는 목적과 적용환경이 다르지만 자동 방수라는 공통 원리를 가진다.',detail:['간이스프링클러는 비교적 단순한 구성으로 초기화재 제어를 목표로 하고, 화재조기진압용 헤드는 고위험 저장공간 등에서 강한 방수로 조기진압을 목표로 하는 개념으로 구분한다.'],must:['간이 = 단순화된 자동소화','조기진압용 = 조기진압 목적'],traps:['두 설비의 세부 설치기준을 소방학개론 핵심범위와 혼동하지 않는다.'],source:'2026 예방실무1 PDF 321·333쪽',deepSections:[sec('범위 원칙','시험에서는 세부 수치보다 목적·작동원리 차이를 우선한다.')]});
put('F07-C07',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'물분무·미분무소화설비는 작은 물방울을 이용해 냉각과 증발에 의한 열흡수, 산소농도 저감 등의 효과를 높인다.',detail:['물방울이 작아질수록 표면적이 커져 열교환과 증발이 빨라질 수 있다.','화재 종류와 전기·유류 등 대상 특성에 맞춰 적용방식이 달라진다.'],must:['미세 물방울','냉각·열흡수','대상 특성 고려'],traps:['일반 물줄기와 완전히 동일한 작동효과로 보지 않는다.'],source:'2026 예방실무1 PDF 328쪽',deepSections:[sec('왜 미세하게 만드는가','표면적 증가로 열을 빠르게 흡수하고 수증기 형성에 의한 부가 소화효과를 얻는다.')]});
put('F07-C08',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'포소화설비는 물과 포원액·공기를 혼합해 형성한 포로 유면을 덮어 증기 발생과 산소 접촉을 억제한다.',detail:['특히 가연성액체 화재에서 액면 피복과 재발화 억제가 중요하다.','포가 깨지거나 오염되면 피복효과가 떨어질 수 있으므로 유면을 안정적으로 덮는 개념을 이해한다.'],must:['유면 피복','증기 억제','재발화 방지'],traps:['포를 단순히 물보다 차가운 냉각제로만 설명하지 않는다.'],source:'2026 예방실무1 PDF 347쪽',deepSections:[sec('제4류와 연결','인화성액체는 증기연소이므로 포가 액면을 덮어 증기발생을 억제하는 원리와 연결한다.')]});
put('F07-C09',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'이산화탄소·할로겐화합물·불활성기체 등 가스계 소화설비는 방호공간에 소화농도를 형성해 산소농도 저하 또는 연쇄반응 억제 등으로 소화한다.',detail:['잔여물이 적어 전기·정밀설비 공간에 유리할 수 있지만 인명안전과 방출 전 경보·대피가 매우 중요하다.'],must:['가스계 소화','방호공간 농도 형성','인명안전·대피'],traps:['사람이 있는 공간에서 안전확인 없이 방출하는 것으로 이해하지 않는다.'],source:'2026 예방실무1 PDF 432쪽',deepSections:[sec('약제별 차이','CO₂는 주로 질식·냉각, 일부 청정소화약제는 연쇄반응 억제와 열흡수 등 약제별 메커니즘 차이가 있다.')]});
put('F07-C10',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'분말소화설비는 분말약제를 방사해 연쇄반응 억제와 질식 등의 효과로 화재를 소화한다.',detail:['분말의 종류에 따라 적응화재가 달라지며 제3종 분말은 ABC 화재에 대응하는 대표 약제로 연결해 이해한다.'],must:['분말약제','부촉매/연쇄반응 억제','종별 적응화재'],traps:['모든 분말이 A·B·C급에 동일하게 적응한다고 외우지 않는다.'],source:'2026 예방실무1 PDF 415쪽',deepSections:[sec('소화약제와 연결','F04 분말소화약제의 주성분·적응화재를 설비의 방사원리와 연결한다.')]});
put('F07-C11',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'자동화재탐지설비는 감지기가 화재징후를 감지해 수신기로 신호를 보내고 경보장치를 통해 사람에게 화재를 알리는 설비다.',detail:['감지기 → 중계/회로 → 수신기 → 경보의 흐름을 이해하면 구성요소 문제를 풀기 쉽다.','소화설비가 직접 화재를 끄는 것과 달리 자동화재탐지는 탐지와 통보가 주 기능이다.'],must:['감지기','수신기','경보','탐지·통보 기능'],traps:['감지기가 작동하면 스프링클러 헤드가 반드시 자동 개방된다고 연결하지 않는다.'],source:'2026 예방실무1 PDF 23쪽',deepSections:[sec('스프링클러와 비교','자동화재탐지 = 감지·경보, 스프링클러 = 열에 의해 헤드가 작동해 직접 방수.')]});
put('F07-C12',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'비상경보·비상방송·자동화재속보·누전·가스누설 관련 설비는 위험을 감지하거나 재실자·관계기관에 신속히 알리는 경보설비군이다.',detail:['비상방송은 음성으로 피난정보를 전달하고, 자동화재속보는 화재신호를 외부에 자동 통보하는 개념으로 구분한다.','누전·가스누설 경보는 화재 자체보다 화재로 이어질 수 있는 전기·가스 위험을 조기에 알리는 역할을 한다.'],must:['비상경보','비상방송','자동화재속보','누전/가스누설'],traps:['각 설비의 “감지 대상”과 “통보 대상”을 바꾸지 않는다.'],source:'2026 예방실무1 PDF 18쪽',deepSections:[sec('분류법','무엇을 감지하는가 / 누구에게 알리는가 두 질문으로 구분한다.')]});
put('F07-C13',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'피난구조설비는 화재 시 사람이 안전한 곳으로 이동하거나 구조될 수 있도록 피난기구·유도등·비상조명·인명구조기구 등을 제공한다.',detail:['피난방향을 알려주는 설비와 실제 이동을 돕는 기구, 구조대상자를 보호하는 장비를 구분해 이해한다.'],must:['피난기구','유도등·유도표지','비상조명','인명구조기구'],traps:['피난구조설비를 직접 화재를 소화하는 설비로 분류하지 않는다.'],source:'2026 예방실무1 PDF 465쪽',deepSections:[sec('사용 관점','정전·연기·혼잡 상황에서 피난자가 방향과 출구를 잃지 않게 돕는다는 목적을 중심으로 본다.')]});
put('F07-C14',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'소화용수설비는 소방대가 화재진압에 필요한 물을 안정적으로 확보할 수 있도록 하는 수원·급수 설비다.',detail:['상수도소화용수·소화수조 등은 직접 자동소화하기보다 현장 소방활동에 필요한 물을 공급하는 목적을 이해한다.'],must:['소방용수 확보','소방대 사용 지원'],traps:['소화용수설비와 옥내소화전 같은 직접 방수설비의 기능을 혼동하지 않는다.'],source:'2026 예방실무1 PDF 201쪽',deepSections:[sec('핵심구분','“물을 저장/공급”하는 설비인지 “물을 화점에 방수”하는 설비인지 구분한다.')]});
put('F07-C15',{status:'verified',sourcePrecision:'exact-pdf-page-anchor',summary:'소화활동설비는 연결송수관·연결살수·제연·비상콘센트·무선통신보조 등 소방대의 진입·방수·배연·통신을 지원한다.',detail:['제연설비는 연기의 이동을 제어해 피난과 소방활동 환경을 개선하고, 연결송수관은 소방대가 고층 등 필요한 지점에 물을 공급하도록 돕는다.','비상콘센트와 무선통신보조설비는 현장 장비 전원과 통신을 지원한다.'],must:['연결송수','제연','비상콘센트','무선통신보조'],traps:['소화활동설비를 모두 자동소화설비로 묶지 않는다.'],source:'2026 예방실무1 PDF 167·174·433·482쪽',deepSections:[sec('기능 묶기','방수지원 / 연기제어 / 전원지원 / 통신지원으로 나누면 기억하기 쉽다.')]});

const EXTRA_DETAIL={
'F05-C02':'시험에서는 제1류의 산화성이라는 공통성질과 조연성, 가연물·환원성물질과의 혼촉위험을 한 묶음으로 비교하고, 개별 품목의 성질은 별도로 구분해 판단한다.',
'F05-C03':'제2류는 연소하기 쉬운 고체라는 공통점이 있지만 금속분·황·적린 등 품목에 따라 연소형태와 소화 시 주의점이 달라 대표물질의 성상까지 연결해 학습한다.',
'F05-C04':'제3류 문제는 공기 접촉에 의한 자연발화 위험과 물 접촉에 의한 금수성 위험을 나누어 읽고, 물질 확인 전 임의 주수하지 않는 판단원칙과 연결한다.',
'F05-C05':'제4류는 인화점·증기발생·유면확산 개념을 함께 보고, 누출된 액체의 확대와 점화원 관리, 포를 이용한 액면 피복 같은 대응원리를 서로 연결해 이해한다.',
'F05-C07':'제6류는 강한 산화성이라는 점에서 제1류와 공통점이 있지만 액체라는 물리적 상태와 누출 확산 특성이 달라 혼촉방지와 누출관리까지 함께 고려한다.',
'F06-C01':'조사자는 소방활동 중 관찰된 최초 상황과 진압 이후 현장을 구분해 기록하고, 확인된 사실·관계자 진술·분석 결과가 섞이지 않도록 증거의 출처를 명확히 남겨야 한다.',
'F06-C02':'화재현장은 안전이 확보된 뒤 출입을 통제하고 전체→중간→근접 순서로 사진과 위치관계를 기록하면 흔적을 훼손하기 전에 조사 당시 상태를 재구성하는 데 도움이 된다.',
'F06-C03':'발화원인 판단은 가능한 가설을 여러 개 세운 뒤 현장흔적·전기설비·사용행위·연소확대 방향 등과 모순되는 가설을 배제하는 방식으로 접근해야 성급한 단정을 줄일 수 있다.',
'F06-C04':'피해기록은 조사 시점과 범위, 피해대상, 사진·도면·목록을 서로 연결해 남기고, 원인조사와 피해조사 자료가 이후에도 추적 가능하도록 일관된 식별정보를 사용한다.',
'F07-C01':'각 설비는 화재를 직접 끄는지, 사람에게 알리는지, 피난을 돕는지, 물을 공급하는지, 소방대 활동을 지원하는지를 기준으로 분류하면 설비명 암기보다 안정적으로 구분할 수 있다.',
'F07-C02':'소화기 사용은 화재종류에 맞는 약제를 선택한 뒤 안전핀 제거·노즐 방향 확보·방사라는 기본 흐름으로 이해하고, 연기와 열이 급격히 증가하면 즉시 피난으로 전환한다.',
'F07-C04':'옥외소화전은 외부에서 소방용수를 사용할 수 있는 방수거점이라는 점이 핵심이며, 건물 내부 초기진압용 옥내소화전과 사용위치·주 사용상황을 비교해서 구분한다.',
'F07-C06':'화재조기진압용 스프링클러는 일반 헤드보다 높은 방수성능으로 화재를 초기에 강하게 제어하는 목적을 이해하고, 간이스프링클러는 비교적 단순한 구성으로 초기화재 제어를 돕는 설비로 구분한다.',
'F07-C07':'미분무는 미세한 물방울의 넓은 표면적을 이용해 빠른 열흡수와 수증기 형성 효과를 얻으며, 일반 스프링클러·물분무와는 방사형태와 적용 목적을 구분해 공부한다.',
'F07-C08':'포는 유류 표면을 연속적으로 덮어 가연성증기의 방출을 줄이는 것이 중요하므로, 포막을 깨뜨리는 강한 직사 방수나 불필요한 교란을 피한다는 운용원리와 연결한다.',
'F07-C09':'가스계 설비는 방호구역의 밀폐성과 소화농도 유지가 성능에 영향을 주므로 방출 전 사람의 대피와 방출 후 환기·재진입 안전까지 하나의 운용 흐름으로 이해한다.',
'F07-C10':'분말은 방사 후 시야저하와 잔여물이 생길 수 있고 재발화 가능성도 확인해야 하므로, 약제 종류별 적응화재와 사용 후 안전확인까지 묶어 학습한다.',
'F07-C11':'자동화재탐지설비는 감지기 종류별 감지대상이 다르더라도 최종적으로 수신기에 신호를 전달해 경보·연동을 시작한다는 공통 흐름을 중심으로 이해한다.',
'F07-C13':'피난구조설비는 정전이나 연기 속에서도 피난방향을 인지하게 하는 유도설비와 실제 탈출을 돕는 피난기구의 역할이 다르므로 기능별로 나누어 기억한다.',
'F07-C14':'소화용수설비는 자체적으로 화점을 감지하거나 자동 방수하는 장치가 아니라, 화재진압 시 필요한 물을 확보·공급하기 위한 기반시설이라는 점에서 소화설비와 구분된다.'
};
for(const [id,text] of Object.entries(EXTRA_DETAIL)){
  const p=P[id];if(!p)continue;
  p.detail=[...(p.detail||[]),text];
}
function ensureDeep(pack,concept){
  if(!pack||!concept)return;
  const sections=[...(pack.deepSections||[])];
  if(!sections.length){
    sections.push(sec('개념 이해',pack.summary||`${concept.title}의 핵심 개념을 공식 근거 중심으로 정리한다.`,pack.detail||[]));
    if((pack.flow||[]).length)sections.push(sec('평가·처치 흐름',(pack.flow||[]).join(' → ')));
    if((pack.must||[]).length)sections.push(sec('시험에서 반드시 기억',(pack.must||[]).join(' · ')));
    if((pack.traps||[]).length)sections.push(sec('혼동 주의',(pack.traps||[]).join(' ')));
  }
  pack.deepSections=sections;
  pack.studyDepth='expanded-2026';
}
for(const c of V.curriculum.concepts)ensureDeep(P[c.id]||V.contentPacks.get(c.id),c);
V.contentRich2026={version:'2026-rich-study-v1',deepConcepts:V.curriculum.concepts.filter(c=>(P[c.id]||{}).deepSections?.length).length,fireAdded:['F05','F06','F07'],pageAnchorPending:V.curriculum.concepts.filter(c=>['F05','F06','F07'].includes(c.scopeId)&&P[c.id]?.status==='scope-verified').map(c=>c.id)};
})();
;

